		"**天机化禄** 在财帛：",
		"**太阴化忌（庙旺）** 在财帛：",
		"财帛宫太阴，入庙大富，太阴主田宅与房产，财来自房地产或稳定型投资；落陷则财运起伏，难以长期积累。化禄时财运极佳，是命盘中最强的财富象征之一；善于细水长流地积累财富，适合长期理财规划。",
		"▶ 化忌：化忌，男命婆媳不和，感情多障碍。",
		"**天梁化权（庙旺）** 在命宫：",
		"天梁老星守命，有长辈缘，主荫，福厚寿长，处事老道，善逢凶化吉。宜法律、医学、教育、宗教领域，孤独倾向较重，适合晚婚。倪海夏说：\"天梁为监察御史，不宜取富，遇化禄者贪图名利，有不宜见禄之说\"——然化科则名声远播，化权则权威大增，是很好的学术权威型格局。天梁守命者，一生中多有逢凶化吉的能力，在危难中往往能化险为夷，有独特的保护力。",
		"**巨门（落陷）** 在夫妻：",
		"夫妻宫巨门，感情中口舌之争较多，双方需要耐心沟通与相互包容。配偶口才好，但也因此容易争吵；化禄则口才化为甜言蜜语，感情改善；化忌则言语矛盾加剧，需双方学会沉默与克制，感情关系中的口舌之争容易积累伤害。",
