		"◇ **天钺在父母**：母亲或女性长辈为第一贵人",
		"你的事业格局以\"专\"和\"荫\"为核心，靠专业权威和帮助他人的能力积累事业声誉，越是在有社会价值的领域越能发光。最适合的行业包括法律、医学、宗教、心理学、教育、咨询顾问、公益慈善或任何需要专业权威和救助色彩的领域，在能\"帮人解困\"的职业中使命感最强、发展最好。职场风格上你是团队中的智囊和稳定器，能在混乱中保持冷静，提供有分量的意见，但有时态度过于高冷，让人觉得难以接近。创业 vs 打工上，天梁在有一定权威背书的机构中发展更稳，若创业宜在专业服务领域建立个人品牌，依靠声誉积累客户，不适合快消型或需要大量社交拓展的商业模式。贵人往往是比你年长、学识渊博的长辈或行业权威，贵人通过知识传授和关键引荐影响你的人生。职场人际上你的形象是可信赖的专家，但需要注意主动建立连接，不要只等他人来找你，适度主动拓展能带来更多机会。最大职场风险是原地踏步，因为过于专注专业而忽略了在机构中的政治关系维护。财与职的关系上，专业声誉是财运基础，声誉越高、资历越深，收入天花板越高。天梁女命的事业最大优势是「权威感+独立性」——古书说天梁女命「孤克」反而在专业型职场中变成优势：你不依附于任何派系，专注于专业本身，因此在律师、医生、大学教授、宗教导师、公益领袖等\"靠专业服务社会\"的角色中能走得远。但天梁女命的职场专属课题是「事业与婚姻的二选一倾向」——古书警示女命天梁「克夫刑子」，现代解读为天梁女命因事业心强、独立性强，传统婚姻模式难以容纳；建议天梁女命接受这种特质，事业为主轴是合理选择，但不必为「单身」感到自我怀疑。生育规划上天梁女命较适合晚育（35+），事业稳定后再考虑生育，对孩子的成长更有助力。",
		"太阳星守命，男命主贵不主富——古诀云「太阳主贵，太阴主富」，太阳守命者重名声与地位甚于实际财富积累。太阳入庙（卯至申宫）则大吉，名利兼收；落陷（酉至寅宫）则劳而无获，付出多回报少，需换方向。女命太阳守命，倪海夏说：「太阳在女人命中，代表先生、丈夫、儿子、父亲」——此即「父夫子三男象」之论：太阳主男性象，女命太阳的人生轨迹紧紧绕着父亲、丈夫、儿子三大男性贵人转动；命宫太阳的女命，丈夫往往公众形象好，事业心强，但相处时间有限。太阳守命者处事光明磊落，不藏心机，重名誉与面子，有博爱精神；外表阳光，声音宏亮，是公众喜爱的类型。",
