		"◇ **天钺在田宅**：家族中女性长辈为家业支柱",
		"你的事业格局以\"辅\"为核心，最能发光的位置是大平台中的核心支撑岗位，而非最前台的领军角色，幕后的力量是你的专长。最适合的行业包括行政管理、法律事务、会计财务、人力资源、秘书文书、大型企业运营或任何需要规范执行和流程管理的岗位，在制度健全的大机构中效率最高。职场风格上你是团队中的执行核心，把工作做得有条不紊，值得信赖，但不善于主动争取资源和晋升机会，需要更主动地展示自己的贡献。创业 vs 打工上，天相明显更适合在成熟平台工作，若创业宜找一个有野心有资源的合伙人主导大方向，自己负责内部管理和执行，分工明确时效果好。贵人往往是机构内部的直属上司或机构外的权威人士，贵人以稳定支持和长期提携的方式出现，不是一次性的助力。职场人际上你处事公平，但有时候过于顾全大局而牺牲自身利益，需要在维护和谐和保护自己之间找到平衡。最大职场风险是功劳被他人占据，以及因为太\"老实\"而被视为理所当然，需要主动为自己的贡献发声。财与职的关系上，收入稳定但增长偏慢，副业可以从自身技能延伸，如提供专业咨询或兼职等。天相女命的事业最大优势是「最被信任的女员工」——稳重老实让上司放心把重要的、需要保密的、需要细致执行的工作交给你。但这也是天相女命的职场陷阱：你被定位成\"执行型助手\"而非\"接班人\"，玻璃天花板比其他主星女命都厚。要打破天花板，必须主动做三件事：（1）每年至少向上司提一次明确的升职诉求；（2）参与公司战略决策的讨论而不只做执行；（3）建立职场之外的专业身份（行业协会、外部讲师、行业写作）。生育与事业平衡上，天相女命的产假回归常常被同事认为\"理所应当承担更多家务向工作的妥协\"，需要从产前就明确边界。",
