		"   化禄，以智慧与变通生财，知识型或策划型收入最顺遂，财来自脑力与人脉。",
		"◇ **天魁在仆役**：朋友圈男性贵人多",
		"◇ **天钺在父母**：母亲或女性长辈为第一贵人",
		"你的事业格局以\"美\"和\"情\"为核心，在需要细腻感知、审美表达和情感联结的领域最能发挥价值。最适合的行业包括房地产、文化艺术、设计、时尚美容、心理咨询、教育培训、财务管理或任何需要细腻服务的行业，在有温度、有美感的工作环境中效率最高。职场风格上你是团队中情绪氛围的管理者，能察觉到同事之间的微妙紧张并加以化解，做事细心，但在竞争激烈的环境中容易感到不适应。创业 vs 打工上，太阴在稳定机构中工作较为顺遂，若创业宜选择审美型、情感型的细分市场，如个人品牌、设计、咨询或与生活方式相关的领域。贵人往往是在生活和工作上能给你资源和平台的女性长辈，或者有品位有资源的圈子。职场人际上你擅长处理微妙的人际关系，但要注意不要因为太善于迎合而失去自己的职业立场，关键时刻要敢于表达不同意见。最大职场风险是情绪波动影响工作状态，以及太在意他人评价而无法集中专注。财与职的关系上，在自己擅长的领域深耕，专业声誉越高收入越稳，副业可以围绕审美和情感服务延伸。太阴是14主星中对女命最有利的星——古书明载「女命太阴最吉」，温婉细腻的气质让你在房地产、设计、心理、教育、美容、文化等审美与情感行业中具有先天竞争优势。但太阴女命的事业最大隐忧是「情绪化导致的职业波动」——当家庭、感情或个人状态不佳时，工作输出明显下滑，容易给上司\"不稳定\"的印象。建议把生活与工作的边界严格分开，建立情绪低谷时的最小可执行任务清单。生育与事业的平衡上，太阴女命对子女有天然的强情感投入，产后回归职场时的心理拉扯感比其他主星女命强；建议提前规划育儿支援，避免独自承担。中年后（40+）太阴女命可考虑转向自由职业（设计师、心理顾问、私人投顾），更符合天性。",
		"官禄宫太阴，适合房地产、文化艺术、财务规划、时尚美容、餐饮服务等需要审美与细心的行业。女命在此宫极为有利，入庙则职业顺遂发展良好；落陷则职业起伏较大，宜寻找更适合自己的方向。化禄则财禄兼顾；化权则在自己的领域很有话语权。",
		"   化忌，男命婆媳不和，感情多障碍；女命情绪困扰与妇科健康需特别注意，宜积极就医。",
		"**天同** 在财帛：",
