		"你的事业格局以\"破\"和\"变\"为核心，在变革和创新的环境中最能发挥价值，守旧和重复是你最难忍受的职业状态。最适合的行业包括科技创新、旅游贸易、国际商务、先锋艺术、军事外交、改革型管理或任何需要开拓精神和勇于打破现状的领域，\"走天下\"的路线最适合你。职场风格上你是那个敢于提出不同意见、推动变革的人，在需要突破的时候能发挥最大价值，但在需要稳定执行的阶段往往兴趣锐减，容易影响团队稳定性。创业 vs 打工上，破军非常适合创业，尤其在高度创新型的领域，靠一技之长打天下的模式最适合，但需要找到一个注重细节和稳定的合伙人来弥补自己的弱项。贵人往往来自天南海北，通过旅途、跨界和特殊际遇带来关键机会，不拘于某一固定来源，可以说\"天下之大皆有贵人\"。职场人际上流动性强，不同时期身边的人会有较大变化，不必对旧关系太执着，拥抱新机遇是你的职场优势。最大职场风险是有始无终，频繁换赛道导致专业积累不够深，以及在重要项目的执行期失去动力。财与职的关系上，财运与变动直接相关，每一次成功的破局都可能带来财运的大幅提升，化禄时\"破而后立\"的财运改善尤为明显。",
		"本宫主星：破军（庙旺）",
		"官禄宫破军，适合技术专业、先锋科技、旅游贸易、开创型事业，有破旧立新的精神；英星入庙（子午宫）则男命武职大成；不宜守旧，需在变动中创造价值。化禄则财来自开创，破而后立；化权则开拓力更强，是先锋者的事业格局。",
		"**贪狼** 在财帛：",
		"财帛宫贪狼，财运与欲望同旺，花钱也多，有偏财运，赌运或投机运有时较旺。逢火铃则偏财暴发；化禄则才艺可变现，财来多元。惟需防挥霍无度，贪狼欲望强，消费也强，需刻意培养储蓄意识与守财能力，否则财来财去积累困难。",
		"**七杀（庙旺）** 在命宫：",
		"七杀将星守命，孤独果决，意志坚强，有冒险精神，宜军警、创业、高风险高回报行业。倪海夏言\"七杀临身终不美\"，天生孤克，一生多奋斗；但七杀朝斗格（子午宫或寅申宫，对宫紫微天府）则\"爵禄荣昌\"，主武职大贵，是化凶为吉的上等格局。七杀守命者，人生往往需要自己拼出来，靠自身的意志力与执行力征服一切。",
		"**紫微化科** 在夫妻：",
		"夫妻宫紫微，配偶气质不凡，有帝王般的存在感与强烈的自我意识，同样主观强势，不轻易低头。两人婚姻中容易出现\"双帝争位\"的局面，各执己见，需要一方学会适当退让，否则争吵不断。宜晚婚，婚前需有充分磨合期；若对宫（命宫）有化禄，则感情较顺遂。夫妻宫紫微者，配偶往往在社会上有一定地位或气场，是能够令人信服的伴侣，但婚姻经营需要双方共同努力。",
		"▶ 化科：化科守命（或三方），名声广播，文教方面成就显著，贵人运佳，在需要名誉的职业中最能发光。",
		"**天相** 在夫妻：",
		"夫妻宫天相，配偶忠实可靠，重承诺，婚姻稳定，是长期陪伴型的伴侣。感情以稳定和谐为主，不够浪漫激情，但忠诚度高，是经营长久婚姻的好配置；需主动制造生活情趣，避免感情流于平淡。配偶在生活中是可信赖的伴侣，踏实可靠，能给予安全感。",
		"🟡 **紫微化科**（落夫妻）",
