		"你的事业格局以\"艺\"和\"欲\"为核心，靠多元才艺和强烈的进取心在社交型行业中找到位置，中晚年才是真正的事业爆发期。最适合的行业包括艺术表演、餐饮酒水、娱乐传媒、旅游贸易、美容美发、商贸谈判或任何需要个人魅力和社交能力的行业，在有人气有热度的场合表现最佳。职场风格上你是团队里的活跃分子，善于在重要场合展示才华，拓展人脉，但在需要持续沉淀和深耕的工作上耐性有限，容易三分钟热度。创业 vs 打工上，贪狼有一定的创业冲动，尤其在餐饮、娱乐或个人品牌领域，但需要有稳重的合伙人管财务，自己专注拓展市场和关系。贵人往往来自圈子中的人气人物或社交核心人士，通过人脉引荐带来的机会是你最主要的贵人运。职场人际上你人缘极好，但需要警惕因为喜新厌旧而频繁更换工作，不利于职业深度积累，建议在一个方向至少坚持5-7年再做大调整。最大职场风险是分散精力、缺乏专注，以及因感情问题影响工作表现。财与职的关系上，你的收入高峰在中年，越积累越好，早年收入波动，需要耐心等待厚积薄发。",
		"本宫主星：贪狼（庙旺）",
		"官禄宫贪狼，适合娱乐、艺术表演、餐饮、政界、社交媒体、销售等行业，口才与才艺是核心竞争力，人脉是最大资产。逢火星或铃星，形成火贪/铃贪格，在此宫则事业有暴发之机；化权则在自己的领域有强大影响力，可独立一面；化禄则财来自才艺与人脉，是非常顺遂的事业格局。",
		"**七杀（庙旺）** 在财帛：",
		"财帛宫七杀，财从努力与冒险中来，赚钱需付出极大努力，财运起伏较大；不怕苦、不怕累是最大优势，大起大落都有可能。需防冲动投资导致大亏，宜谨慎评估风险再行动；若三方有化禄加持，则财运相对稳定，努力最终得到回报。",
		"**破军（庙旺）** 在命宫：",
		"破军守命，叛逆创新，六亲缘薄，一生多变动，宜独立自主的专业技术路线。倪海夏说：\"破军星是要流浪在外，走天下的，专业技术专长，她要捧着饭碗走天下\"——守命者最宜靠一技之长闯天下，不宜守旧，主动拥抱变化才是正道。英星入庙（子午宫）则男命英挺威武，可有武职大成；化禄则\"破而后立\"，在破坏中开创新天地。",
		"**武曲（庙旺）** 在夫妻：",
		"夫妻宫武曲，配偶性格强势果断，务实重行动，少甜言蜜语，以实际行动表达爱意。武曲有孤克之气，婚姻需要较长的磨合期；化忌时\"刑囚之象\"影响夫妻关系，需防刑克，婚姻有坎坷，双方须共同努力。配偶在财务或事业上往往相当能干，是有实力的伴侣，但婚姻中需要主动增加情感的温度。",
		"三方四正范围内暂无本命四化落入，格局较为中性，需重点看落宫主星、对宫借星与煞曜吉曜组合来判断吉凶起伏。",
		"🟢 **天机化禄**（落父母）→ 上司贵人助力，文书顺利",
